package dev.pedro.learning.ecommerce.inventory.api; import dev.pedro.learning.ecommerce.inventory.domain.*; import java.time.Instant; import java.util.UUID; public record ReservationResponse(UUID id,UUID orderId,UUID productId,int quantity,ReservationStatus status,Instant createdAt,Instant releasedAt){public static ReservationResponse from(InventoryReservation r){return new ReservationResponse(r.id,r.orderId,r.productId,r.quantity,r.status,r.createdAt,r.releasedAt);}}